// 模拟TCP可靠传输的伪代码
class ReliableSender {
    int base = 0;          // 窗口基序号
    int nextSeq = 0;       // 下一个待发送序号
    int windowSize = 4;    // 发送窗口大小
    Map<Integer, Timer> timers = new HashMap<>();

    // 发送数据
    void send(byte[] data) {
        if (nextSeq < base + windowSize) {
            Segment seg = new Segment(nextSeq, data);
            transmit(seg);
            startTimer(nextSeq, RTO);
            nextSeq++;
        } else {
            // 窗口已满，等待ACK
            queue(data);
        }
    }

    // 收到ACK
    void onAckReceived(int ackNum) {
        base = max(base, ackNum + 1);
        cancelTimer(ackNum);
        if (base == nextSeq) {
            stopAllTimers();
        } else {
            startTimer(base, RTO);
        }
    }

    // 超时重传
    void onTimeout(int seq) {
        transmit(getSegment(seq));  // 重传该段
        startTimer(seq, RTO * 2);   // 指数退避
    }

    // 快速重传：收到3个重复ACK
    void onDuplicateAck(int ackNum, int count) {
        if (count >= 3) {
            transmit(getSegment(ackNum));
            // 进入快速恢复
        }
    }
}
